<?php

$finder = (new PhpCsFixer\Finder())
    ->in(__DIR__)
    ->exclude('var')
    ->exclude('vendor')
    // Dummy Symfony application generated locally by tests_e2e/run_e2e.sh.
    ->exclude('e2e-test')
    // Benchmark components generated by tests/Visual/ComponentGenerator.
    ->exclude('tests/Visual/Generated')
    ->exclude('tests/Integration/Fixtures')
;

return (new PhpCsFixer\Config())
    ->setRules([
        '@PSR12' => true,
        'array_syntax' => ['syntax' => 'short'],
    ])
    ->setFinder($finder)
;
